$ErrorActionPreference = "Stop"

$folder = 'C:\Users\Lenovo\OneDrive\Desktop\AI Attendance PDFs'
$edge = 'C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
New-Item -ItemType Directory -Force -Path $folder | Out-Null

function New-Pdf {
    param([string]$Name,[string]$Html)
    $safe = ($Name -replace '[\\/:*?"<>|]', '').Trim()
    $htmlPath = Join-Path $folder ($safe + '.html')
    $pdfPath = Join-Path $folder ($safe + '.pdf')
    Set-Content -Path $htmlPath -Value $Html -Encoding UTF8
    & $edge --headless --disable-gpu --print-to-pdf="$pdfPath" --print-to-pdf-no-header "$htmlPath" | Out-Null
    Start-Sleep -Milliseconds 1500
    Remove-Item -LiteralPath $htmlPath -Force -ErrorAction SilentlyContinue
}

